                : LTS_VERSIONS_SORTED_ASCENDING.find { it.isCompatibleWith(version) }
        new VersionSpec(desiredJdkVersion: [desiredJdkVersion, ltsVersion].max(), desiredSourceCompatibility: [desiredSourceCompatibility, ltsVersion].max())
