        private final List<String> unownedFiles;

        IntegrityReport(File folder, List<Entry> entries, List<String> unownedFiles) {
            this.folder = folder;
            this.entries = entries;
            this.unownedFiles = unownedFiles;
        }

        static IntegrityReport empty(File folder) {
            return new IntegrityReport(folder, Collections.emptyList(), Collections.emptyList());
        }

        boolean hasProblems() {
            if (!unownedFiles.isEmpty()) {
                return true;
            }
            for (Entry entry : entries) {
                if (entry.broken || entry.resolved || entry.shared || entry.misplaced || entry.colliding || entry.occupied) {
                    return true;
                }
            }
            return false;
        }

        String asMessage() {
            StringBuilder result = new StringBuilder("Violation store integrity check failed for ")
                    .append(folder.getAbsolutePath()).append(":\n");
            appendEntries(result, "broken", filter(entry -> entry.broken));
            appendEntries(result, "resolved", filter(entry -> entry.resolved));
            appendEntries(result, "shared", filter(entry -> entry.shared));
            appendEntries(result, "misplaced", filter(entry -> entry.misplaced));
            appendEntries(result, "colliding", filter(entry -> entry.colliding));
            appendEntries(result, "occupied", filter(entry -> entry.occupied));
            if (!unownedFiles.isEmpty()) {
                result.append("unowned files:\n");
                for (String file : unownedFiles) {
                    result.append("  ").append(file).append('\n');
                }
            }
            return result.toString().trim();
        }

        private List<Entry> filter(java.util.function.Predicate<Entry> predicate) {
            return entries.stream().filter(predicate).sorted(ENTRY_COMPARATOR).collect(toList());
        }

        private static void appendEntries(StringBuilder result, String condition, List<Entry> entries) {
            if (entries.isEmpty()) {
